// ---- helpers (kept by tools/art/frame_fit.py when it rewrites the table above)

/** A frame's fit to its idle pose: its scale on top of the idle's, and where its box's bottom-centre goes from the
 *  idle box's, in idle heights (y down). */
export interface FrameFit { scale: number; dx: number; dy: number }

export function frameFit(id: string): FrameFit | null {
  const r = FRAME_FIT[id];
  return r ? { scale: r[0], dx: r[1], dy: r[2] } : null;
}

/** A box in idle heights, from the idle box's bottom-centre (y down): the top-left and the size. */
export interface FitBox { x: number; y: number; w: number; h: number }

/** The frame's box as fitted, in the idle's (null without an entry: the frame is drawn as before). */
export function fitBox(id: string): FitBox | null {
  const r = FRAME_FIT[id];
  if (!r) return null;
  const h = r[0] * r[3], w = h * r[4];
  return { x: r[1] - w / 2, y: r[2] - h, w, h };
}

/** Two poses of one figure in one picture (the site's shop window: the figure and its blow, in turn): the box round
 *  both as fitted, its width / height, and each pose's place in it in per cent (left, top, width, height). Null if
 *  either has no entry or they are not one figure's. */
export function fitStage(idle: string, alt: string): { ar: number; a: [number, number, number, number]; b: [number, number, number, number] } | null {
  const A = fitBox(idle), B = fitBox(alt);
  if (!A || !B || FRAME_FIT[idle][0] !== 1 || !alt.startsWith(idle)) return null;
  const x0 = Math.min(A.x, B.x), y0 = Math.min(A.y, B.y), x1 = Math.max(A.x + A.w, B.x + B.w), y1 = Math.max(A.y + A.h, B.y + B.h);
  const W = x1 - x0, H = y1 - y0;
  const pc = (b: FitBox): [number, number, number, number] =>
    [b.x - x0, b.y - y0, b.w, b.h].map((v, i) => Math.round((v / (i % 2 ? H : W)) * 10000) / 100) as [number, number, number, number];
  return { ar: Math.round((W / H) * 10000) / 10000, a: pc(A), b: pc(B) };
}
